// Some portions generated by Claude
import {graphNodeSize} from '../../../../main/frontend/graph-explorer/graph-geometry.ts';
import {SpatialGrid} from '../../../../main/frontend/graph-explorer/spatial-grid.ts';

/** Exact card intersections via the broad phase; bounded for sparse 50k maps. */
export function indexedIntersections(graph, positions) {
  const index = new SpatialGrid(256), candidates = [];
  let count = 0;
  for (const node of graph.nodes) {
    const p = positions.get(node.id), size = graphNodeSize(node);
    const b = {minX: p.x - size.width / 2, maxX: p.x + size.width / 2, minY: p.y - size.height / 2, maxY: p.y + size.height / 2};
    count += index.search(b.minX + 1e-5, b.minY + 1e-5, b.maxX - 1e-5, b.maxY - 1e-5, candidates).length;
    index.insert(b);
  }
  return count;
}

export function intersectingGroupBoxes(graph, positions, groups) {
  const byId = new Map(graph.nodes.map(n => [n.id, n]));
  const boxes = groups.filter(g => g.nodeIds.length > 1).map(g => {
    const nodes = g.nodeIds.map(id => ({...positions.get(id), ...graphNodeSize(byId.get(id))}));
    return {minX: Math.min(...nodes.map(n => n.x - n.width / 2)), maxX: Math.max(...nodes.map(n => n.x + n.width / 2)),
      minY: Math.min(...nodes.map(n => n.y - n.height / 2)), maxY: Math.max(...nodes.map(n => n.y + n.height / 2))};
  });
  let count = 0;
  for (let a = 0; a < boxes.length; a++) for (let b = a + 1; b < boxes.length; b++) {
    const p = boxes[a], q = boxes[b];
    if (p.minX < q.maxX && q.minX < p.maxX && p.minY < q.maxY && q.minY < p.maxY) count++;
  }
  return count;
}
